export function validateUEPCompliance(request: any): { valid: boolean; errors: ValidationError[] } {
  const errors: ValidationError[] = [];
  
  if (!request.metadata?.traceId) {
    errors.push({
      field: 'metadata.traceId',
      message: 'UEP requests must include traceId',
      code: 'UEP_TRACE_ID_MISSING'
    });
  }

  if (!request.metadata?.timestamp) {
    errors.push({
      field: 'metadata.timestamp',
      message: 'UEP requests must include timestamp',
      code: 'UEP_TIMESTAMP_MISSING'
    });
  }

  if (!request.metadata?.requestId) {
    errors.push({
      field: 'metadata.requestId',
      message: 'UEP requests must include requestId',
      code: 'UEP_REQUEST_ID_MISSING'
    });
  }

  if (!request.metadata?.agentId) {
    errors.push({
      field: 'metadata.agentId',
      message: 'UEP requests must include agentId',
      code: 'UEP_AGENT_ID_MISSING'
    });
  }

  // Validate timestamp format
  if (request.metadata?.timestamp) {
    try {
      const date = new Date(request.metadata.timestamp);
      if (isNaN(date.getTime())) {
        errors.push({
          field: 'metadata.timestamp',
          message: 'Timestamp must be a valid ISO 8601 date string',
          code: 'UEP_INVALID_TIMESTAMP',
          value: request.metadata.timestamp
        });
      }
    } catch (error) {
      errors.push({
        field: 'metadata.timestamp',
        message: 'Timestamp must be a valid ISO 8601 date string',
        code: 'UEP_INVALID_TIMESTAMP',
        value: request.metadata.timestamp
      });
    }
  }

  // Validate trace ID format (simple format check)
  if (request.metadata?.traceId && !/^[a-zA-Z0-9_-]+$/.test(request.metadata.traceId)) {
    errors.push({
      field: 'metadata.traceId',
      message: 'Trace ID must contain only alphanumeric characters, underscores, and hyphens',
      code: 'UEP_INVALID_TRACE_ID_FORMAT',
      value: request.metadata.traceId
    });
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

export function validateCompatibility(requestVersion: string): { compatible: boolean; message?: string } {
  const protocolVersion = '1.0.0';
  
  if (!requestVersion) {
    return {
      compatible: false,
      message: 'Request version is required'
    };
  }

  // Parse semantic versions
  const parseVersion = (version: string) => {
    const parts = version.split('.');
    return {
      major: parseInt(parts[0]) || 0,
      minor: parseInt(parts[1]) || 0,
      patch: parseInt(parts[2]) || 0
    };
  };

  try {
    const requested = parseVersion(requestVersion);
    const protocol = parseVersion(protocolVersion);
    
    // Major version must match exactly
    if (requested.major !== protocol.major) {
      return {
        compatible: false,
        message: `Major version mismatch: requested ${requestVersion}, protocol ${protocolVersion}`
      };
    }
    
    // Minor version: requested cannot be greater than protocol
    if (requested.minor > protocol.minor) {
      return {
        compatible: false,
        message: `Minor version not supported: requested ${requestVersion}, protocol ${protocolVersion}`
      };
    }
    
    return { compatible: true };
  } catch (error) {
    return {
      compatible: false,
      message: `Invalid version format: ${requestVersion}`
    };
  }
}

export function validateCompleteRequest(request: any): { valid: boolean; errors: ValidationError[] } {
  const allErrors: ValidationError[] = [];

  // Validate UEP compliance
  const uepValidation = validateUEPCompliance(request);
  allErrors.push(...uepValidation.errors);

  // Validate UEP request structure
  const requestValidation = validateUEPRequest(request);
  allErrors.push(...requestValidation.errors);

  // Validate method-specific data
  if (request.method === 'parse-prd') {
    const methodValidation = validateParsePrd(request.data);
    allErrors.push(...methodValidation.errors);
  } else if (request.method === 'validate-prd') {
    const methodValidation = validateValidatePrd(request.data);
    allErrors.push(...methodValidation.errors);
  }

  // Validate version compatibility
  if (request.metadata?.version) {
    const compatibilityCheck = validateCompatibility(request.metadata.version);
    if (!compatibilityCheck.compatible) {
      allErrors.push({
        field: 'metadata.version',
        message: compatibilityCheck.message || 'Version incompatible',
        code: 'UEP_VERSION_INCOMPATIBLE',
        value: request.metadata.version
      });
    }
  }

  return {
    valid: allErrors.length === 0,
    errors: allErrors
  };
}